import React from 'react';

const AnalysisColumns = ({ analysisData }) => {
  if (!analysisData) {
    return <div>No analysis data available</div>;
  }

  return (
    <div className="analysis-table">
      <div className="analysis-column">
        <h3>Compatibility</h3>
        <div className="analysis-content">
          {analysisData.compatibility ? (
            <div dangerouslySetInnerHTML={{ __html: analysisData.compatibility.replace(/\n/g, '<br/>') }} />
          ) : (
            <div>No compatibility analysis available</div>
          )}
        </div>
      </div>
      
      <div className="analysis-column">
        <h3>Gaps</h3>
        <div className="analysis-content">
          {analysisData.gaps ? (
            <div dangerouslySetInnerHTML={{ __html: analysisData.gaps.replace(/\n/g, '<br/>') }} />
          ) : (
            <div>No gaps analysis available</div>
          )}
        </div>
      </div>
      
      <div className="analysis-column">
        <h3>Research</h3>
        <div className="analysis-content">
          {analysisData.research ? (
            <div dangerouslySetInnerHTML={{ __html: analysisData.research.replace(/\n/g, '<br/>') }} />
          ) : (
            <div>No research data available</div>
          )}
        </div>
      </div>
    </div>
  );
};

export default AnalysisColumns; 