import React from 'react';
import ResumeLabel from './common/ResumeLabel';
import SearchParametersDisplay from './searched/SearchParametersDisplay';
import AnalysisColumns from './analyzed/AnalysisColumns';
import AnalyzedStatusDisplay from './analyzed/AnalyzedStatusDisplay';
import AnalyzedActionButtons from './analyzed/AnalyzedActionButtons';
import LoadingSpinner from './ui/LoadingSpinner';
import useAnalyzedScreen from '../hooks/useAnalyzedScreen';
import useTheme from '../hooks/useTheme';

const AnalyzedScreen = ({ appState, updateAppState, navigateTo }) => {
  const { theme } = useTheme();
  const { 
    resumeFile, 
    analysisStatus, 
    analysisProgress, 
    analysisError, 
    handleBack, 
    handleExit, 
    handleRetryAnalysis 
  } = useAnalyzedScreen({ 
    appState, 
    updateAppState,
    navigateTo 
  });
  
  const analysisData = appState.analysisData;
  const selectedJob = appState.selectedJobForAnalysis;

  // Show loading state while analysis is running
  if (analysisStatus === 'starting' || analysisStatus === 'running') {
    return (
      <>
        <div className="left-panel">
          <div className="form-group">
            <ResumeLabel resumeFile={resumeFile} />
          </div>
          <SearchParametersDisplay appState={appState} />
        </div>
        <div className="right-panel">
          <div className="screen-header">
            {selectedJob ? 
              `Analyzing: ${selectedJob.title} at ${selectedJob.company}` : 
              'Analyzing Job...'
            }
          </div>
          <div className="loading-container">
            <LoadingSpinner />
            <div className="loading-text">
              {analysisStatus === 'starting' ? 'Starting analysis...' : 'Analyzing job requirements...'}
            </div>
            {analysisProgress > 0 && (
              <div className="progress-text">Progress: {analysisProgress}%</div>
            )}
          </div>
        </div>
      </>
    );
  }

  // Show error state
  if (analysisStatus === 'error' || analysisStatus === 'timeout') {
    return (
      <>
        <div className="left-panel">
          <div className="form-group">
            <ResumeLabel resumeFile={resumeFile} />
          </div>
          <SearchParametersDisplay appState={appState} />
        </div>
        <div className="right-panel">
          <div className="screen-header">
            {selectedJob ? 
              `Analysis Error: ${selectedJob.title} at ${selectedJob.company}` : 
              'Analysis Error'
            }
          </div>
          <div className="error-container">
            <div className="error-message">
              {analysisError || 'Analysis failed. Please try again.'}
            </div>
            <button 
              className="retry-button" 
              onClick={handleRetryAnalysis}
            >
              Retry Analysis
            </button>
          </div>
        </div>
      </>
    );
  }

  return (
    <>
      <div className="left-panel">
        {/* Resume Section */}
        <div className="form-group">
          <ResumeLabel resumeFile={resumeFile} />
        </div>

        {/* Search Parameters Display */}
        <SearchParametersDisplay appState={appState} />

        {/* Status Display */}
        <AnalyzedStatusDisplay appState={appState} />

        {/* Action Buttons */}
        <AnalyzedActionButtons
          analysisData={analysisData}
          handleBack={handleBack}
          handleExit={handleExit}
        />
      </div>

      <div className="right-panel">
        <div className="screen-header">
          {selectedJob ? 
            `Analyzed: ${selectedJob.title} at ${selectedJob.company}` : 
            'Job Analysis'
          }
        </div>
        
        {analysisData ? (
          <AnalysisColumns analysisData={analysisData} />
        ) : (
          <div className="no-data-message">
            No analysis data available. Please try again.
          </div>
        )}
      </div>
    </>
  );
};

export default AnalyzedScreen; 