import { useState, useEffect } from 'react';

const useAnalysis = () => {
  const [analysisProcessId, setAnalysisProcessId] = useState(null);
  const [analysisStatus, setAnalysisStatus] = useState('idle');
  const [analysisProgress, setAnalysisProgress] = useState(0);
  const [analysisData, setAnalysisData] = useState(null);
  const [analysisError, setAnalysisError] = useState(null);

  const startAnalysis = async (selectedJobForAnalysis, resumeData) => {
    try {
      setAnalysisStatus('starting');
      setAnalysisError(null);
      setAnalysisProgress(0);

      const apiUrl = process.env.REACT_APP_API_URL || 'http://localhost:3002/api';
      
      const response = await fetch(`${apiUrl}/analyze-job`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          selectedJobForAnalysis,
          resumeData
        }),
      });

      if (!response.ok) {
        throw new Error(`Analysis start failed: ${response.statusText}`);
      }

      const data = await response.json();
      setAnalysisProcessId(data.processId);
      setAnalysisStatus('running');
      
      return data.processId;
    } catch (error) {
      console.error('Analysis start error:', error);
      setAnalysisError(error.message);
      setAnalysisStatus('error');
      throw error;
    }
  };

  const checkAnalysisStatus = async (processId) => {
    try {
      const apiUrl = process.env.REACT_APP_API_URL || 'http://localhost:3002/api';
      
      const response = await fetch(`${apiUrl}/analysis-status/${processId}`);
      
      if (!response.ok) {
        throw new Error(`Status check failed: ${response.statusText}`);
      }

      const data = await response.json();
      
      setAnalysisProgress(data.progress || 0);
      
      if (data.status === 'completed') {
        setAnalysisStatus('completed');
        setAnalysisData(data.analysisData);
        return data.analysisData;
      } else if (data.status === 'error') {
        setAnalysisStatus('error');
        setAnalysisError('Analysis process failed');
        throw new Error('Analysis process failed');
      }
      
      return null;
    } catch (error) {
      console.error('Status check error:', error);
      setAnalysisError(error.message);
      setAnalysisStatus('error');
      throw error;
    }
  };

  const pollAnalysisStatus = async (processId) => {
    const pollInterval = setInterval(async () => {
      try {
        const result = await checkAnalysisStatus(processId);
        if (result) {
          clearInterval(pollInterval);
          return result;
        }
      } catch (error) {
        clearInterval(pollInterval);
        throw error;
      }
    }, 2000); // Poll every 2 seconds

    // Set a timeout to stop polling after 5 minutes
    setTimeout(() => {
      clearInterval(pollInterval);
      if (analysisStatus === 'running') {
        setAnalysisStatus('timeout');
        setAnalysisError('Analysis timed out');
      }
    }, 5 * 60 * 1000);
  };

  const resetAnalysis = () => {
    setAnalysisProcessId(null);
    setAnalysisStatus('idle');
    setAnalysisProgress(0);
    setAnalysisData(null);
    setAnalysisError(null);
  };

  return {
    analysisProcessId,
    analysisStatus,
    analysisProgress,
    analysisData,
    analysisError,
    startAnalysis,
    checkAnalysisStatus,
    pollAnalysisStatus,
    resetAnalysis
  };
};

export default useAnalysis;
