import { useState, useEffect } from 'react';
import useAnalysis from './useAnalysis';

const useAnalyzedScreen = ({ appState, updateAppState, navigateTo }) => {
  const [resumeFile, setResumeFile] = useState({
    name: appState.resume || 'Default Resume.pdf',
    file: null,
    isDefault: appState.resume === 'Default Resume.pdf'
  });

  const {
    analysisProcessId,
    analysisStatus,
    analysisProgress,
    analysisData,
    analysisError,
    startAnalysis,
    checkAnalysisStatus,
    pollAnalysisStatus,
    resetAnalysis
  } = useAnalysis();

  // Keep resumeFile in sync with appState.resume
  useEffect(() => {
    if (appState.resume && appState.resume !== resumeFile.name) {
      if (appState.resume === 'Default Resume.pdf') {
        setResumeFile({ name: 'Default Resume.pdf', file: null, isDefault: true });
      } else {
        setResumeFile({ name: appState.resume, file: null, isDefault: false });
      }
    }
  }, [appState.resume]);

  // Start analysis when component mounts if we have a selected job
  useEffect(() => {
    if (appState.selectedJobForAnalysis && analysisStatus === 'idle') {
      handleStartAnalysis();
    }
  }, [appState.selectedJobForAnalysis]);

  // Poll for analysis status when running
  useEffect(() => {
    if (analysisStatus === 'running' && analysisProcessId) {
      pollAnalysisStatus(analysisProcessId);
    }
  }, [analysisStatus, analysisProcessId]);

  // Update appState when analysis completes
  useEffect(() => {
    if (analysisStatus === 'completed' && analysisData) {
      updateAppState({ analysisData });
    }
  }, [analysisStatus, analysisData, updateAppState]);

  const handleStartAnalysis = async () => {
    try {
      if (!appState.selectedJobForAnalysis) {
        throw new Error('No job selected for analysis');
      }

      // Get resume data
      let resumeData = null;
      if (appState.resumeData) {
        resumeData = appState.resumeData;
      } else if (resumeFile.file) {
        // Read resume file content
        const content = await readResumeFile(resumeFile.file);
        resumeData = { content, fileName: resumeFile.name };
      }

      await startAnalysis(appState.selectedJobForAnalysis, resumeData);
    } catch (error) {
      console.error('Failed to start analysis:', error);
    }
  };

  const readResumeFile = async (file) => {
    return new Promise((resolve, reject) => {
      const reader = new FileReader();
      reader.onload = (e) => resolve(e.target.result);
      reader.onerror = reject;
      reader.readAsText(file);
    });
  };

  const handleBack = () => {
    resetAnalysis();
    navigateTo('scored');
  };

  const handleExit = () => {
    window.close();
  };

  const handleRetryAnalysis = () => {
    resetAnalysis();
    handleStartAnalysis();
  };

  return {
    resumeFile,
    analysisStatus,
    analysisProgress,
    analysisError,
    handleBack,
    handleExit,
    handleRetryAnalysis
  };
};

export default useAnalyzedScreen; 